function filletFramePoint(frame,p){return frame.origin.map((x,i)=>x+p.reduce((sum,q,j)=>sum+q*frame.axes[j][i],0));}
function filletCurvePoint(c,t){return c.kind==='line'?c.a.map((x,i)=>x+t*(c.b[i]-x)):filletFramePoint(c.frame,[c.radius*Math.cos(t),c.radius*Math.sin(t),0]);}
