function filletUV(c,t){return c.kind==='affine'?c.origin.map((x,i)=>x+t*c.direction[i]):c.center.map((x,i)=>x+c.radius*(i===0?Math.cos(c.start_angle+t):Math.sin(c.start_angle+t)));}
